import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

const teamId = typeof window !== 'undefined' ? window.POSTHOG_APP_CONTEXT?.current_team?.id : undefined

const DEFAULT_CATEGORY_RAIL_DOCKED = false

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterCategoryLayoutLogicValues {
    categoryRailPinned: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterCategoryLayoutLogicActions {
    setCategoryRailPinned: (categoryRailPinned: boolean) => {
        categoryRailPinned: boolean
    }
}

export type taxonomicFilterCategoryLayoutLogicType = MakeLogicType<
    taxonomicFilterCategoryLayoutLogicValues,
    taxonomicFilterCategoryLayoutLogicActions
>

export const taxonomicFilterCategoryLayoutLogic = kea<taxonomicFilterCategoryLayoutLogicType>([
    path(['lib', 'components', 'TaxonomicFilter', 'taxonomicFilterCategoryLayoutLogic']),
    actions({
        setCategoryRailPinned: (categoryRailPinned: boolean) => ({ categoryRailPinned }),
    }),
    reducers({
        categoryRailPinned: [
            DEFAULT_CATEGORY_RAIL_DOCKED,
            { persist: true, prefix: `${teamId}__` },
            {
                setCategoryRailPinned: (_, { categoryRailPinned }) => categoryRailPinned,
            },
        ],
    }),
    listeners(() => ({
        setCategoryRailPinned: ({ categoryRailPinned }) => {
            posthog.capture('taxonomic filter category rail toggled', { docked: categoryRailPinned })
        },
    })),
])
